import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addMonths_TriageGen1Test {

    @Test
    public void testAddMonths_Positive() {
        // Test adding a standard number of months
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(3);
        Assert.assertEquals(2023, dt.getYear());
        Assert.assertEquals(4, dt.getMonthOfYear());
        Assert.assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_Negative() {
        // Test subtracting months
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 0, 0, 0);
        dt.addMonths(-2);
        Assert.assertEquals(2023, dt.getYear());
        Assert.assertEquals(3, dt.getMonthOfYear());
        Assert.assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_Zero() {
        // Test adding zero months
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(0);
        Assert.assertEquals(2023, dt.getYear());
        Assert.assertEquals(1, dt.getMonthOfYear());
        Assert.assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_YearBoundary() {
        // Test crossing the year boundary
        MutableDateTime dt = new MutableDateTime(2023, 11, 1, 0, 0, 0, 0);
        dt.addMonths(3);
        Assert.assertEquals(2024, dt.getYear());
        Assert.assertEquals(2, dt.getMonthOfYear());
    }

    @Test
    public void testAddMonths_DayOverflow() {
        // Test behavior when adding months results in a day that doesn't exist in the target month
        // Jan 31 + 1 month should result in Feb 28 or 29
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        Assert.assertEquals(2023, dt.getYear());
        Assert.assertEquals(2, dt.getMonthOfYear());
        Assert.assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_LeapYear() {
        // Test leap year logic
        // Jan 31, 2024 + 1 month -> Feb 29, 2024
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        Assert.assertEquals(29, dt.getDayOfMonth());
        Assert.assertEquals(2, dt.getMonthOfYear());

        // Jan 31, 2023 + 1 month -> Feb 28, 2023
        MutableDateTime dtNonLeap = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dtNonLeap.addMonths(1);
        Assert.assertEquals(28, dtNonLeap.getDayOfMonth());
    }

    @Test
    public void testAddMonths_LargeValue() {
        // Test adding a very large number of months
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.addMonths(1200); // 100 years
        Assert.assertEquals(2100, dt.getYear());
        Assert.assertEquals(1, dt.getMonthOfYear());
    }

    @Test
    public void testAddMonths_LargeNegativeValue() {
        // Test adding a very large negative number of months
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.addMonths(-1200); // -100 years
        Assert.assertEquals(1900, dt.getYear());
        Assert.assertEquals(1, dt.getMonthOfYear());
    }
}
